={{ (() => {
  const source = $('API 키 폐기·재발급·IP 차단').first().json ?? {};
  const response = $('대응 결과 확인').first().json ?? {};
  const incident = $('인시던트 생성 확인').first().json ?? {};
  const webhook = $('Webhook').first().json ?? {};
  const body = webhook.body ?? webhook;
  const find = (value, key) => {
    if (!value || typeof value !== 'object') return undefined;
    if (value[key] !== undefined && value[key] !== null && value[key] !== '') return value[key];
    for (const child of Object.values(value)) {
      const found = find(child, key);
      if (found !== undefined) return found;
    }
    return undefined;
  };
  const apiKeyId = find(source, 'api_key_id') ?? find(body, 'api_key_id');
  const clientIp = find(source, 'client_ip') ?? find(body, 'client_ip');
  const reason = find(source, 'detection_reason') ?? find(body, 'detection_reason') ?? 'not_allowed_ip';
  const eventType = find(source, 'event_type') ?? find(body, 'event_type') ?? 'api_key_compromised';
  const incidentId = find(source, 'incident_id') ?? find(response, 'incident_id') ?? find(body, 'incident_id') ?? find(incident, 'created_incident_id') ?? find(incident, 'incident_id');
  if (!apiKeyId || !clientIp || !incidentId) throw new Error('대시보드 전송값 누락: api_key_id, client_ip 또는 incident_id');
  return { event_type: eventType, incident_id: incidentId, api_key_id: apiKeyId, client_ip: clientIp, severity: '높음', status: '열림', decision: '거부', action: '키 폐기·IP 차단', reason };
})() }}

